--
-- Table structure for table `posts`
--

DROP TABLE IF EXISTS `posts`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `posts` (
  `post_id` int NOT NULL,
  `post_date` date DEFAULT NULL,
  `post_type` varchar(20) DEFAULT NULL,
  `topic` varchar(50) DEFAULT NULL,
  `caption_length` int DEFAULT NULL,
  `hashtags_count` int DEFAULT NULL,
  `video_duration` int DEFAULT NULL,
  `posting_hour` int DEFAULT NULL,
  `likes` int DEFAULT NULL,
  `comments` int DEFAULT NULL,
  `shares` int DEFAULT NULL,
  `saves` int DEFAULT NULL,
  `reach` int DEFAULT NULL,
  `impressions` int DEFAULT NULL,
  `followers` int DEFAULT NULL,
  `engagement_rate` decimal(8,3) DEFAULT NULL,
  `save_rate` decimal(8,3) DEFAULT NULL,
  `share_rate` decimal(8,3) DEFAULT NULL,
  `reach_ratio` decimal(8,3) DEFAULT NULL,
  `day_of_week` varchar(15) DEFAULT NULL,
  `post_month` varchar(10) DEFAULT NULL,
  `is_prime_time` tinyint DEFAULT NULL,
  `performance_level` varchar(10) DEFAULT NULL,
  PRIMARY KEY (`post_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

